package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import com.insight.quantlife.*;
/** Dedicated synthetic AVD: actual WebView -> native SQLite, mock model only. */
public class WorkClockTest extends ChatRedesignTest {
 void seedClock()throws Exception{
  check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.2"),"Baseline signed 1.7.2");holdAutomation();JSONObject snap=init();
  try(TrackStore t=new TrackStore(getTargetContext())){snap.put("raw",t.diagnostics("2026-12-15").getJSONArray("rawPoints")).put("gpx",t.gpx("2026-12-15"));}
  try(FileOutputStream f=getTargetContext().openFileOutput("clock-upgrade.json",0)){f.write(snap.toString().getBytes("UTF-8"));}
 }
 void clockMock()throws Exception{chatMock();h.js("window.__modelMode='empty';const mockCall=LifeNative.call;LifeNative.call=function(action,payload,rid){if(action==='ask'&&JSON.parse(payload).tool.name==='plan_record_search'&&__modelMode==='tool'){__calls.push(JSON.parse(payload));setTimeout(()=>nativeReply({id:rid,data:{text:JSON.stringify({intent:'update',topic:'',keywords:[],dateStart:'',dateEnd:''}),model:'synthetic-planner'}}),15);return;}if(action==='ask'&&JSON.parse(payload).tool.name==='prepare_life_records'&&__modelMode==='tool'){const p=JSON.parse(payload);__calls.push(p);setTimeout(()=>nativeReply({id:rid,data:{text:JSON.stringify({answer:'待确认',records:[],citations:[],actions:[{kind:'end_work',at:__at}]}),model:'synthetic-tool-model'}}),15);return;}if(action==='ask'&&__modelMode==='malformed'){__calls.push(JSON.parse(payload));setTimeout(()=>nativeReply({id:rid,data:{text:'只口头回复而未输出操作',model:'synthetic-missing-tool'}}),15);return;}mockCall(action,payload,rid)}");}
 JSONObject active()throws Exception{JSONArray a=init().getJSONArray("records");for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(r.optString("type").equals("work")&&r.optString("workEnd").isEmpty())return r;}return null;}
 void confirmClock(String text)throws Exception{sendText(text);jsCheck("document.querySelectorAll('[data-confirm-change]').length===1","Clock statement yields one confirmable operation: "+text);click("[data-confirm-change]");until("!document.querySelector('[data-confirm-change]')");}
 void workflow()throws Exception{
  holdAutomation();JSONObject before=init();if(!phase.equals("workflow")){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getTargetContext().openFileInput("clock-upgrade.json")){byte[] b=new byte[4096];int n;while((n=in.read(b))>0)out.write(b,0,n);}JSONObject snap=new JSONObject(out.toString("UTF-8"));
  check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.3"),"Signed 1.7.3 cover installation");for(String k:new String[]{"records","wikiPages","messages","chatSession"})check(snap.get(k).toString().equals(before.get(k).toString()),"Upgrade preserves "+k);JSONObject s=snap.getJSONObject("settings"),t=before.getJSONObject("settings");s.remove("wikiAutomation");t.remove("wikiAutomation");check(s.toString().equals(t.toString()),"Model/current-search configuration preserved");
  try(TrackStore ts=new TrackStore(getTargetContext())){check(snap.getString("gpx").equals(ts.gpx("2026-12-15"))&&snap.getJSONArray("raw").toString().equals(ts.diagnostics("2026-12-15").getJSONArray("rawPoints").toString()),"Upgrade does not touch raw GPS or D trajectory");}
  }
  // Only synthetic work fixtures in this explicitly disposable AVD are removed.
  JSONArray all=before.getJSONArray("records");for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("type").equals("work"))h.call("deleteRecord",new JSONObject().put("id",all.getJSONObject(i).getString("id")));
  h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",model("SYNTHETIC-ONLY"))));h.call("newChat",new JSONObject());reload();holdAutomation();clockMock();click("[data-page=chat]");
  jsCheck("!document.querySelector('.app-header')&&!document.querySelector('#open-settings')&&!document.querySelector('.chat-title')","No top branding/model/title bar");jsCheck("document.querySelectorAll('.chat-toolbar').length===1&&document.querySelectorAll('.bottom-nav button').length===4","History/new/tools controls and four navigation tabs retained");jsCheck("getComputedStyle(document.querySelector('.welcome-mark')).backgroundColor==='rgb(33, 106, 84)'","Original green theme retained");jsCheck("document.documentElement.scrollWidth<=innerWidth+1","Phone layout has no horizontal overflow");Thread.sleep(700);h.screenshot("clock-chat-home-1.7.3.png");
  click("[data-action=chat-history]");click("#drawer-model");jsCheck("document.querySelector('#api-key')!==null","Model settings reachable from history drawer");click(".model-back");
  sendText("我上班了");check(active()==null,"Clock preview does not write before confirmation");click("[data-drop-change]");check(active()==null,"Ignoring operation leaves database untouched");
  h.js("__modelMode='malformed'");confirmClock("我上班了");JSONObject current=active();check(current!=null,"Missing/malformed model action still creates confirmed actual shift");String rid=current.getString("id"),start=current.getString("workStart");h.js("__modelMode='empty'");
  sendText("我上班了");check(active().getString("id").equals(rid),"Duplicate start cannot create second active shift");jsCheck("!document.querySelector('[data-confirm-change]')&&document.querySelector('#chat-messages').innerText.includes('不能重复上班')","Duplicate start gives actionable explanation");
  Thread.sleep(1100);sendText("我开始休息了");check(active().getJSONArray("breaks").length()==0,"Rest preview has not altered native DB");h.js("ChatUI.bottom()");Thread.sleep(700);h.screenshot("clock-rest-preview-1.7.3.png");click("[data-confirm-change]");until("!document.querySelector('[data-confirm-change]')");check(active().getJSONArray("breaks").length()==1&&active().getString("id").equals(rid),"Confirmed rest updates same native shift");
  Thread.sleep(1100);confirmClock("休息结束了");check(!active().getJSONArray("breaks").getJSONObject(0).getString("end").isEmpty(),"Confirmed return closes native rest interval");Thread.sleep(1100);confirmClock("我下班了");JSONObject ended=find(rid);check(active()==null&&ended.getString("workStart").equals(start)&&!ended.getString("workEnd").isEmpty(),"Confirmed end retains shift start and finishes actual shift");
  jsCheck("__calls.every(p=>p.tool.name==='prepare_life_records')&&__calls[0].tool.parameters.properties.actions.items.properties.at!==undefined","Common clock commands skip unreliable intent planner and expose timed actions");
  String date=new JSONArray(h.js("(()=>{let d=new Date();d.setDate(d.getDate()-1);return [LifeDomain.localDate(d)]})()")).getString(0);
  sendText(date+" 09:00上班");jsCheck("!document.querySelector('[data-confirm-change]')&&document.querySelector('#chat-messages').innerText.includes('完整的上下班')","Backdated open start reports later-shift overlap before confirmation");
  // Remove only the just-verified synthetic lifecycle shift to isolate a historical fixture.
  h.call("deleteRecord",new JSONObject().put("id",rid));reload();holdAutomation();clockMock();click("[data-page=chat]");
  confirmClock(date+" 09:00上班");rid=active().getString("id");confirmClock(date+" 12:00开始休息");confirmClock(date+" 13:00休息结束");
  // A richer command uses an actual model action with at and auto-targets unique active shift.
  h.js("__modelMode='tool';__at="+JSONObject.quote(date+"T18:00:00"));confirmClock("请为我登记下班并关联当前班次");ended=find(rid);check(ended.getString("workEnd").equals(date+"T18:00:00")&&ended.getInt("durationMinutes")==480,"Model timed tool persists exact 8 net hours after one hour rest");h.js("__modelMode='empty'");
  sendText("现在下班");check(active()==null,"End without a shift never creates invented records");jsCheck("document.querySelector('#chat-messages').innerText.includes('先记录上班')&&!document.querySelector('[data-confirm-change]')","Missing start gives clear recovery hint");
  click("[data-page=records]");jsCheck("!document.querySelector('.app-header')&&document.querySelector('[data-action=quick-add]')!==null","Record page has no brand header and retains add-entry");click("[data-action=quick-add]");jsCheck("document.querySelectorAll('[data-quick]').length===5","All five manual record types remain accessible");click("#close-editor");click("[data-record-tab=work]");Thread.sleep(700);h.screenshot("clock-work-records-1.7.3.png");jsCheck("document.documentElement.scrollWidth<=innerWidth+1","Work page fits phone after removing header");
 }
 @Override public void onStart(){Bundle result=new Bundle();try{h=new MainHost(this);h.open();if(phase.equals("seed"))seedClock();else if(phase.equals("keyboard"))keyboardUi();else workflow();result.putString("stream","PASS "+passed+" clock/native/UI checks; phase="+phase+"; mock model only\n");finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream","FAIL after "+passed+": "+e+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
